function usesEveryLetter(text: string): boolean {
  const FULL = (1 << 26) - 1;
  let mask = 0;
  for (let i = 0; i < text.length; i++) {
    mask |= 1 << (text.charCodeAt(i) - 97);
    if (mask === FULL) return true;
  }
  return false;
}

